    if (norm_val <= ADCS_EPS_NORM) {
        *c = adcs_mat3_identity();
        return ADCS_E_DEGENERATE;
    }
    r1 = adcs_vec3_scale(pi, 1.0 / norm_val);

    // r2_temp = cross(r1, si)
